window.VO = [{"id":"n01","text":"You're his only alibi.","at":0.24,"t0":0.12,"t1":1.39},{"id":"f00","text":"Tell them I was with you!","at":3.18,"t0":1.59,"t1":3.08},{"id":"n02","text":"Your best friend's locked up for robbing a watch shop.","at":6.66,"t0":3.33,"t1":6.14},{"id":"n03","text":"All the police have is a blurry photo of the robber.","at":12.78,"t0":6.39,"t1":9.155},{"id":"n03a","text":"All he has is you.","at":18.81,"t0":9.405,"t1":10.515},{"id":"o01","text":"Last Tuesday, seven forty. Where were you?","at":21.63,"t0":10.815,"t1":13.735},{"id":"n03b","text":"But do you really remember? Because for you, it was just another Tuesday.","at":30.07,"t0":15.035,"t1":18.92},{"id":"f01","text":"Think, yaar! We were at the chai stall, in the rain! You had ginger chai, you paid twenty rupees!","at":39.54,"t0":19.77,"t1":25.64},{"id":"f01r","text":"Don't you remember?","at":51.88,"t0":25.94,"t1":27.225},{"id":"n04","text":"And now you do.","at":55.05,"t0":27.525,"t1":28.53},{"id":"o02","text":"He says you two were at a chai stall. So what did you drink?","at":57.76,"t0":28.88,"t1":32.475},{"id":"o03","text":"How much did you pay?","at":67.35,"t0":33.675,"t1":35.345},{"id":"o04","text":"Same as his statement.","at":72.89,"t0":36.445,"t1":38.475},{"id":"n06","text":"Everything you know about that night, he told you.","at":78.35,"t0":39.175,"t1":41.575},{"id":"n06b","text":"So where was he, really?","at":84.55,"t0":42.275,"t1":43.505},{"id":"n07","text":"He was here.","at":88.81,"t0":44.405,"t1":45.23},{"id":"o05","text":"Alibi confirmed. He can go.","at":93.46,"t0":46.73,"t1":49.28},{"id":"n08","text":"You just set a robber free.","at":99.56,"t0":49.78,"t1":51.155},{"id":"n09","text":"You were never at that stall. He knew you'd forget.","at":103.31,"t0":51.655,"t1":54.215},{"id":"f02","text":"Thanks, yaar. Next time, I'll pay.","at":109.83,"t0":54.915,"t1":57.095},{"id":"n11","text":"Would your best friend lie for you? Send them this: if anyone asks, I was with you last Tuesday.","at":115.39,"t0":57.695,"t1":62.965},{"id":"n12","text":"But first: what's hanging from his watch?","at":130.93,"t0":65.465,"t1":67.565}];
